import sys


def main():
    data = sys.stdin.read().split()
    n, q = int(data[0]), int(data[1])
    label = list(range(n + 1))
    out = []
    idx = 2
    for _ in range(q):
        t = data[idx]
        a = int(data[idx + 1])
        b = int(data[idx + 2])
        idx += 3
        if t == "1":
            la = label[a]
            lb = label[b]
            if la != lb:
                for v in range(1, n + 1):
                    if label[v] == lb:
                        label[v] = la
        else:
            out.append("YES" if label[a] == label[b] else "NO")
    print("\n".join(out))


main()
